package corpus.iteratorcontract

class ExhaustedSentinel(private val values: List<Int>) : Iterator<Int> {
    private var index = 0
    override fun hasNext(): Boolean = index < values.size
    override fun next(): Int {
        if (!hasNext()) return 0
        return values[index++]
    }
}

