package corpus.iteratorcontract

class DelegatingIterator(values: List<Int>) : Iterator<Int> {
    private val delegate = values.iterator()
    override fun hasNext(): Boolean = delegate.hasNext()
    override fun next(): Int = delegate.next()
}

